class ListNode:
    def __init__(self, val=0, next=None):
        self.val = val
        self.next = next

def deleteNodes(head, m, n):
    curr = head
    while curr:
        # Skip m-1 nodes (keep m nodes)
        for i in range(1, m):
            if curr is None:
                return head
            curr = curr.next
        if curr is None:
            break
        # Delete next n nodes
        temp = curr
        for i in range(n):
            if temp.next:
                temp = temp.next
            else:
                temp = None
                break
        # Connect
        curr.next = temp.next if temp else None
        curr = curr.next
    return head
